 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool SetWindowText(nint hwnd,string value);
 [DllImport("user32.dll")]static extern bool IsWindowVisible(nint hwnd);
 [DllImport("user32.dll")]static extern bool IsWindowEnabled(nint hwnd);
 sealed class OwnPhotoPicker:IDisposable
 {
  readonly Form owner;readonly string path;readonly uint thread=GetCurrentThreadId();readonly System.Windows.Forms.Timer timer=new(){Interval=40};readonly DateTime started=DateTime.UtcNow;bool filled;public bool Submitted{get;private set;}public string? Failure{get;private set;}
  public OwnPhotoPicker(Form owner,string path){this.owner=owner;this.path=Path.GetFullPath(path);timer.Tick+=Tick;timer.Start();}
  void Tick(object? sender,EventArgs e){if(Submitted||Failure is not null)return;EnumThreadWindows(thread,(dialog,_)=>{GetWindowThreadProcessId(dialog,out var pid);var cls=new System.Text.StringBuilder(80);GetClassName(dialog,cls,80);var caption=new System.Text.StringBuilder(160);GetWindowText(dialog,caption,160);if(pid!=Environment.ProcessId||cls.ToString()!="#32770"||!caption.ToString().StartsWith("원본 보존",StringComparison.Ordinal))return true;var owned=false;for(var h=GetWindow(dialog,4);h!=0;h=GetWindow(h,4))if(h==owner.Handle){owned=true;break;}if(!owned)return true;
   var edits=new List<nint>();var diagnostic=new List<object>();EnumChildWindows(dialog,(h,_)=>{GetWindowThreadProcessId(h,out var cp);var cn=new System.Text.StringBuilder(80);GetClassName(h,cn,80);if(cp!=Environment.ProcessId)return true;if(cn.ToString()=="Edit"&&IsWindowVisible(h)&&IsWindowEnabled(h)){diagnostic.Add(new{handle=h.ToInt64(),id=GetDlgCtrlID(h),parentId=GetDlgCtrlID(GetParent(h))});var inFileName=false;for(var parent=GetParent(h);parent!=0&&parent!=dialog;parent=GetParent(parent))if(GetDlgCtrlID(parent)==1148)inFileName=true;if(GetDlgCtrlID(h)==1148||inFileName)edits.Add(h);}return true;},0);
   if(edits.Count!=1){if((DateTime.UtcNow-started).TotalSeconds>4){Failure="Owned filename edit was ambiguous or unavailable";Samples.Add(new{name="owned photo picker unsupported controls",edits=diagnostic});SendMessage(dialog,0x0010,0,0);}return false;}
   var button=GetDlgItem(dialog,1);GetWindowThreadProcessId(button,out var bp);if(button==0||bp!=Environment.ProcessId)return false;if(!filled){Check(SetWindowText(edits[0],path),"Owned native filename input rejected text");filled=true;return false;}Samples.Add(new{name="actual owned photo import picker",processId=pid,dialog=dialog.ToInt64(),filenameEdit=edits[0].ToInt64(),button=button.ToInt64(),scope="Exact owned process/thread/dialog title/owner chain; filename descendant1148 and native Open button only"});Submitted=true;SendMessage(button,0x00f5,0,0);return false;
  },0);}
  public void Dispose(){timer.Stop();timer.Tick-=Tick;timer.Dispose();}
 }
 static TextBox Editor(RecordDocument doc,string name)=>Tree(doc.PropertiesPanel).OfType<TextBox>().Single(c=>c.Name==name);
 static void BindingMatches(RecordDocument doc){var grid=Grid(doc);Check(grid.CurrentRow?.Tag is WorkRecord,"Visual current row is absent");var record=(WorkRecord)grid.CurrentRow!.Tag!;Check(doc.SelectedId==record.Id&&grid.SelectedRows.Count==1&&ReferenceEquals(grid.SelectedRows[0],grid.CurrentRow),"Visual and logical selected row differ");foreach(var text in Tree(doc.PropertiesPanel).OfType<TextBox>())Check(text.Text==record.Fields.GetValueOrDefault(text.Name,""),"Editor differs from visual row: "+text.Name);Check(!doc.IsDirty,"Binding populated a dirty editor");}
 static async Task ImportPhotoPicker(Form owner,RecordDocument photo,string file){var before=Grid(photo).Rows.Count;using var picker=new OwnPhotoPicker(owner,file);Tool(photo,"사진 가져오기").PerformClick();await Until(()=>picker.Submitted||picker.Failure is not null,"Owned import picker never appeared");Check(picker.Submitted,picker.Failure??"Picker not submitted");await Until(()=>Grid(photo).Rows.Count==before+1&&photo.SelectedId is not null&&!photo.IsDirty&&Editor(photo,"title").Text==Path.GetFileName(file)&&Tree(photo).OfType<PictureBox>().Any(p=>p.Image is not null),"First imported photo did not automatically bind editors and preview");}
 static async Task Selection69Checks(WorkbenchForm form,LocalWorkspace store,WorkspaceServices services)
 {
  var projects=(RecordDocument)form.Documents.Single().Document;await projects.Ready;RecordDocument? photo=null;var p1="";var p2="";var photo1="";
  await Test("review69 project bar stays visible and project native saves automatically refresh choices",async()=>{var selector=Tree(form).OfType<ComboBox>().Single(c=>c.DropDownStyle==ComboBoxStyle.DropDownList&&c.Parent is ToolStrip);Samples.Add(new{name="project selector native geometry",visible=selector.Visible,width=selector.Width,height=selector.Height,physicalDpi=selector.DeviceDpi,parentVisible=selector.Parent!.Visible,parentBounds=new[]{selector.Parent.Left,selector.Parent.Top,selector.Parent.Width,selector.Parent.Height},selectorBounds=new[]{selector.Left,selector.Top,selector.Width,selector.Height}});Capture(form,"selection69-project-bar-before-save");Check(selector.Visible&&selector.Width>=200,"Project selector is hidden or too narrow");var strip=(ToolStrip)selector.Parent!;Check(strip.Items.OfType<ToolStripComboBox>().Single().Placement==ToolStripItemPlacement.Main&&strip.DisplayRectangle.Contains(strip.Items.OfType<ToolStripComboBox>().Single().Bounds),"Project selector is in overflow or clipped");Tool(projects,"새 항목").PerformClick();Editor(projects,"title").Text="Selection69 first project";await SaveByButton(projects);p1=projects.SelectedId!;await Until(()=>selector.Items.Cast<object>().Any(i=>i.ToString()=="Selection69 first project"),"New project missing without explicit refresh");BindingMatches(projects);Tool(projects,"새 항목").PerformClick();Check(projects.SelectedId is null&&Grid(projects).CurrentCell is null&&Grid(projects).SelectedRows.Count==0,"New record retained visual old selection");Editor(projects,"title").Text="Selection69 second project";await SaveByButton(projects);p2=projects.SelectedId!;await Until(()=>selector.Items.Cast<object>().Any(i=>i.ToString()=="Selection69 second project"),"Second project not autorefreshed");Ids["selection69-p1"]=p1;Ids["selection69-p2"]=p2;form.SelectProject(p1);Capture(form,"selection69-visible-project-bar");});
  await Test("review69 actual native single-photo picker binds first row editors and large preview immediately",async()=>{photo=await OpenRecord(form,"photos");var file=Path.Combine(Output,"selection69-first.png");using(var image=new Bitmap(96,72)){using var g=Graphics.FromImage(image);g.Clear(Color.DarkCyan);image.Save(file,System.Drawing.Imaging.ImageFormat.Png);}await ImportPhotoPicker(form,photo,file);BindingMatches(photo);photo1=photo.SelectedId!;Ids["selection69-photo1"]=photo1;Check(Editor(photo,"title").Text==Path.GetFileName(file)&&Editor(photo,"assetId").Text.Length>0&&Editor(photo,"sha256").Text.Length==64,"First photo fields stayed blank");Capture(form,"selection69-first-single-photo-bound");});
  await Test("review69 native first photo edit saves existing row instead of creating duplicate",async()=>{Check(photo is not null,"Photo prerequisite");Editor(photo!,"title").Text="Selection69 edited first photo";Check(photo!.IsDirty,"Native text edit did not dirty document");await SaveByButton(photo);BindingMatches(photo);Check(photo.SelectedId==photo1&&(await store.ListAsync(services.Actor,new RecordQuery("photos",p1))).Count==1,"First photo edit duplicated or lost original row");});
  await Test("review69 same-row previous next and toolbar reload preserve photo binding and preview",async()=>{foreach(var action in new[]{"다음 사진","이전 사진","다시 읽기"}){Tool(photo!,action).PerformClick();await Until(()=>Tree(photo!).OfType<PictureBox>().Any(p=>p.Image is not null),"Navigation/reload left single photo preview blank");BindingMatches(photo!);Check(photo!.SelectedId==photo1,"Single-photo navigation changed identity");}});
  await Test("review69 row click refresh and project switch cannot overwrite unsaved native edits",async()=>{var file=Path.Combine(Output,"selection69-second.png");using(var image=new Bitmap(70,60)){using var g=Graphics.FromImage(image);g.Clear(Color.Coral);image.Save(file,System.Drawing.Imaging.ImageFormat.Png);}await ImportPhotoPicker(form,photo!,file);var selected=photo!.SelectedId!;Editor(photo,"caption").Text="Unsaved native caption must survive";var other=Grid(photo).Rows.Cast<DataGridViewRow>().Single(r=>r.Tag is WorkRecord w&&w.Id!=selected);Grid(photo).CurrentCell=other.Cells[0];await Until(()=>Grid(photo).CurrentRow?.Tag is WorkRecord row&&row.Id==selected,"Dirty row click left inconsistent visual selection");Tool(photo,"다시 읽기").PerformClick();form.SelectProject(p2);await Task.Delay(100);Check(photo.SelectedId==selected&&photo.Context.ProjectId==p1&&form.SelectedProjectId==p1&&Editor(photo,"caption").Text=="Unsaved native caption must survive"&&photo.IsDirty,"Dirty protection changed context, values or selection");await SaveByButton(photo);BindingMatches(photo);});
  await Test("review69 project transition clears stale photo immediately and reloads matching context",async()=>{form.SelectProject(p2);await Until(()=>Grid(photo!).Rows.Count==0&&photo!.SelectedId is null&&Editor(photo,"title").Text==""&&Tree(photo).OfType<PictureBox>().All(p=>p.Image is null),"Empty project retained old photo/editor");form.SelectProject(p1);await Until(()=>Grid(photo!).Rows.Count==2&&photo!.SelectedId is not null&&Tree(photo).OfType<PictureBox>().Any(p=>p.Image is not null),"Returning project did not bind first photo");BindingMatches(photo!);form.SelectProject(p2);await Until(()=>Grid(photo!).Rows.Count==0,"Second project did not become empty");await ImportPhotoPicker(form,photo!,Path.Combine(Output,"selection69-first.png"));Ids["selection69-single-photo"]=photo!.SelectedId!;BindingMatches(photo);form.SelectProject(p1);await Until(()=>Grid(photo).Rows.Count==2&&photo.SelectedId is not null,"Original project did not return after single-photo setup");});
  await Test("review69 reopening real project document binds selected first row and edits native fields",async()=>{var another=await OpenRecord(form,"projects");BindingMatches(another);var id=another.SelectedId!;Editor(another,"title").Text="Selection69 reopened project edit";await SaveByButton(another);BindingMatches(another);Check(another.SelectedId==id,"Reopened first project edit created another row");Ids["selection69-project-edit"]=id;form.Documents.Single(d=>ReferenceEquals(d.Document,photo)).Activate();form.SelectProject(p1);});
  await Test("review69 report tab resolves authorized project name instead of internal identifier",async()=>{var report=form.OpenDocument("report-studio");var ready=report.Document.GetType().GetProperty("Ready")?.GetValue(report.Document) as Task;Check(ready is not null,"Report ready task missing");await ready!;Check(!report.Document.Title.Contains(p1,StringComparison.Ordinal)&&!report.Document.Title.EndsWith("선택한 프로젝트",StringComparison.Ordinal),"Report tab exposes ID or unresolved placeholder");var actual=(await store.ListAsync(services.Actor,new RecordQuery("projects"))).Single(r=>r.Id==p1).Fields["title"];Check(report.Document.Title.Contains(actual,StringComparison.Ordinal),"Report title lacks actual project name");Capture(form,"selection69-readable-report-project-title");});
  await Test("borrowed split navigation survives tab switch float return and normal document close",async()=>{var report=form.Documents.Single(d=>d.Module.ModuleId=="report-studio");var navigation=report.Module.CreateLeftPanel(report.Document);var projectsWindow=form.Documents.First(d=>d.Module.ModuleId=="projects");for(var i=0;i<3;i++){projectsWindow.Activate();await Task.Delay(35);report.Activate();await Task.Delay(35);Check(navigation.Visible&&navigation.FindForm()==form,"Report navigation did not return visibly to its owner");}form.ToggleFloating("left");Check(navigation.Visible&&navigation.FindForm()!=form,"Report navigation did not enter floating host");form.ToggleFloating("left");Check(navigation.Visible&&navigation.FindForm()==form,"Report navigation did not return from floating host");report.Close();await Until(()=>report.IsDisposed,"Normal report child close did not finish");Check(navigation.IsDisposed,"Closed report retained borrowed navigation");var reopened=form.OpenDocument("report-studio");await (Task)reopened.Document.GetType().GetProperty("Ready")!.GetValue(reopened.Document)!;Check(reopened.Module.CreateLeftPanel(reopened.Document).Visible,"Reopened report navigation is hidden");await Task.Delay(75);Check(ThreadFault is null,"Borrowed-panel switch/float/close caused owned UI exception");Samples.Add(new{name="borrowed panel normal-close regression",diagnosticLayoutSuspension=false,diagnosticHide=false,retiredNavigationDisposed=navigation.IsDisposed,reopenedActive=form.ActivePanelContextId==reopened.Document.Context.ContextId});});
 }
 static async Task RowOrderChecks(WorkbenchForm form,LocalWorkspace store,WorkspaceServices services)
 {
  var doc=(RecordDocument)form.Documents.Single().Document;await doc.Ready;var ids=new List<string>();
  await Test("row-order creates two native editable records with no injected selection",async()=>{foreach(var title in new[]{"Native row-order A","Native row-order B"}){Tool(doc,"새 항목").PerformClick();Editor(doc,"title").Text=title;await SaveByButton(doc);ids.Add(doc.SelectedId!);}Check(Grid(doc).Rows.Count==2,"Row-order setup count wrong");});
  await Test("row-order CurrentCell change binds the finally highlighted record and saves it once",async()=>{Check(ids.Count==2,"Row-order prerequisite failed");var grid=Grid(doc);void Trace(string kind)=>Samples.Add(new{name="native row event ordering",kind,ticks=System.Diagnostics.Stopwatch.GetTimestamp(),currentRowId=(grid.CurrentRow?.Tag as WorkRecord)?.Id,logicalSelectedId=doc.SelectedId,title=Editor(doc,"title").Text,dirty=doc.IsDirty});EventHandler selection=(_,_)=>Trace("SelectionChanged"),cell=(_,_)=>Trace("CurrentCellChanged");grid.SelectionChanged+=selection;grid.CurrentCellChanged+=cell;try{foreach(var id in new[]{ids[0],ids[1],ids[0]}){Select(doc,id);await Task.Delay(50);Trace("after native event pump");Capture(form,"row-order-"+id);BindingMatches(doc);Check(doc.SelectedId==id,"Highlighted and logical record ID differ after CurrentCell changed");}Editor(doc,"facility").Text="Native row-order persisted edit";await SaveByButton(doc);BindingMatches(doc);var records=await store.ListAsync(services.Actor,new RecordQuery("projects"));Check(records.Count==2&&records.Single(r=>r.Id==ids[0]).Fields.GetValueOrDefault("facility")=="Native row-order persisted edit","Selected row edit was lost or duplicated");}finally{grid.SelectionChanged-=selection;grid.CurrentCellChanged-=cell;}});
 }
 static async Task Selection69BeforeChecks(WorkbenchForm form,LocalWorkspace store,WorkspaceServices services)
 {
  var projects=(RecordDocument)form.Documents.Single().Document;await projects.Ready;var project="";
  await Test("R4-before setup uses native project save and explicit manual selector refresh only",async()=>{Tool(projects,"새 항목").PerformClick();Editor(projects,"title").Text="Selection69 R4 before project";await SaveByButton(projects);project=projects.SelectedId!;await form.RefreshProjectsAsync();form.SelectProject(project);});
  await Test("R4-before reproduces highlighted first photo with unbound logical selection editors and preview",async()=>{Check(project.Length>0,"Before project setup failed");var photo=await OpenRecord(form,"photos");var file=Path.Combine(Output,"selection69-before.png");using(var image=new Bitmap(96,72)){using var g=Graphics.FromImage(image);g.Clear(Color.DarkCyan);image.Save(file,System.Drawing.Imaging.ImageFormat.Png);}using var picker=new OwnPhotoPicker(form,file);Tool(photo,"사진 가져오기").PerformClick();await Until(()=>picker.Submitted||picker.Failure is not null,"Owned before picker did not appear");Check(picker.Submitted,picker.Failure??"Picker not submitted");await Until(()=>Grid(photo).Rows.Count==1,"Before photo import did not create one visual row");await Task.Delay(250);var grid=Grid(photo);var visual=grid.CurrentRow?.Tag as WorkRecord;var logical=photo.SelectedId;var title=Editor(photo,"title").Text;var asset=Editor(photo,"assetId").Text;var hash=Editor(photo,"sha256").Text;var preview=Tree(photo).OfType<PictureBox>().Any(p=>p.Image is not null);Samples.Add(new{name="R4-before actual binding predicates",expectedDefectReproduction=true,visualId=visual?.Id,selectedRows=grid.SelectedRows.Count,logicalSelectedId=logical,title,assetId=asset,sha256=hash,previewLoaded=preview});Capture(form,"selection69-R4-before-unbound-first-photo");Check(visual is not null&&grid.SelectedRows.Count==1&&logical is null&&title==""&&asset==""&&hash==""&&!preview,"Exact R4 before defect was not reproduced; do not interpret as after-fix failure");});
 }
 static async Task Selection69ReopenChecks(WorkbenchForm form,LocalWorkspace store,WorkspaceServices services)
 {
  foreach(var(k,v) in JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(Path.Combine(Output,"fixture-ids.json")))!)Ids[k]=v;
  await Test("review69 fresh process first visible project row matches editor and logical selection",async()=>{var projects=(RecordDocument)form.Documents.Single().Document;await projects.Ready;BindingMatches(projects);Check((await store.ListAsync(services.Actor,new RecordQuery("projects"))).Count==2,"Project edit duplicated rows across restart");});
  await Test("review69 fresh process first photo auto-loads its saved native fields and preview",async()=>{form.SelectProject(Ids["selection69-p2"]);var photo=await OpenRecord(form,"photos");await Until(()=>Tree(photo).OfType<PictureBox>().Any(p=>p.Image is not null),"Fresh-process photo preview stayed blank");BindingMatches(photo);Check(Grid(photo).Rows.Count==1&&photo.SelectedId==Ids["selection69-single-photo"],"Single-photo project changed across restart");Capture(form,"selection69-fresh-photo-bound");});
 }
